"""Sample native layout every quarter second and at edit boundaries; audit safe-area bounds."""
from pathlib import Path
import json,sys
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'videos'/(sys.argv[1] if len(sys.argv)>1 else '12-fabric-motion-refined');shots=json.loads((OUT/'work/shots.json').read_text());duration=json.loads((OUT/'work/render-info.json').read_text())['duration'];times=sorted(set([round(n*.25,3) for n in range(int(duration*4))]+[round(max(0,s['start']+.05),3) for s in shots]+[round(s['end']-.04,3) for s in shots]))
(OUT/'out').mkdir(exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1920,'height':1080});page.goto('http://127.0.0.1:8765/videos/'+OUT.name+'/index.html');page.evaluate('document.fonts.ready');page.wait_for_function('!!window.__timelines?.main')
 result=page.evaluate('''times=>{const bad=[],clips=[...document.querySelectorAll('.clip')];let checked=0;for(const time of times){window.__timelines.main.pause().seek(time);for(const clip of clips){const a=Number(clip.dataset.start),z=a+Number(clip.dataset.duration);clip.style.display=time>=a&&time<z?'':'none'}for(const el of document.querySelectorAll('[data-safe],.ev1-cap .w,video')){if(!el.getClientRects().length)continue;let visible=true;for(let node=el;node;node=node.parentElement){const style=getComputedStyle(node);if(Number(style.opacity)<.02||style.display==='none'){visible=false;break}}if(!visible)continue;const r=el.getBoundingClientRect();const kind=el.dataset.safe||(el.tagName==='VIDEO'?'video':'caption');checked++;let limit=[0,0,1920,1080];if(kind==='content'||kind==='video')limit=[70,138,1850,910];if(kind==='caption')limit=[70,944,1850,1008];if(kind==='provenance')limit=[70,902,1850,934];if(r.left<limit[0]-1||r.top<limit[1]-1||r.right>limit[2]+1||r.bottom>limit[3]+1)bad.push({time,kind,text:el.textContent?.slice(0,90),rect:{left:r.left,top:r.top,right:r.right,bottom:r.bottom},limit});if((kind==='title'||kind==='content')&&el.children.length===0&&(el.scrollWidth>el.clientWidth+2||el.scrollHeight>el.clientHeight+2))bad.push({time,kind,issue:'text overflows its box',text:el.textContent})}}return{samples:times.length,elementsChecked:checked,violations:bad}}''',times)
 (OUT/'out/frame-fit-audit.json').write_text(json.dumps(dict(result,method='DOM bounds at 0.25-second samples plus cut boundaries; transformed wrapper bounds and visible caption words; source-image legibility reviewed separately',resolution=[1920,1080]),indent=2));print(json.dumps({'samples':result['samples'],'elements':result['elementsChecked'],'violations':result['violations'][:10],'total_violations':len(result['violations'])}));browser.close();assert not result['violations'],'Frame-fit audit failed'
